from collections import deque
from collections import defaultdict
import sys
sys.setrecursionlimit(1000000)
for _ in range(int(input())):
	(N, K) = list(map(int, input().split()))
	childnodes = defaultdict(lambda : [])
	for i in range(N - 1):
		(u, v) = list(map(int, input().split()))
		childnodes[u - 1].append(v - 1)
		childnodes[v - 1].append(u - 1)
	arr = [0] * N

	def dfs(node, arr, prev, childnodes):
		if node not in childnodes:
			arr[node] = 1
			return 1
		mx = 0
		for i in childnodes[node]:
			if i != prev:
				mx = max(dfs(i, arr, node, childnodes), mx)
		arr[node] = mx + 1
		return mx + 1
	try:
		dfs(0, arr, 0, childnodes)
	except:
		pass
	ans = [0] * (N + 1)
	for i in range(N):
		try:
			ans[arr[i]] += 1
		except:
			pass
	for i in range(1, len(ans)):
		ans[i] = ans[i] + ans[i - 1]
	print(ans[K])
